DWORD WINAPI GetOwnerModuleFromTcpEntry( PMIB_TCPROW_OWNER_MODULE entry, TCPIP_OWNER_MODULE_INFO_CLASS class,
                                         void *buffer, DWORD *size )
{
    TRACE( "entry %p, class %d, buffer %p, size %p.\n", entry, class, buffer, size );

